    let messages_value = to_chat_messages(&request.messages);
    let messages: Vec<ChatCompletionRequestMessage> = serde_json::from_value(messages_value)
        .map_err(|e: serde_json::Error| ModelError::Other(anyhow::anyhow!(e)))?;

